CustomField.formula:
IF(CONTAINS( $Label.APE_Product_Unit_Link+';'+$Label.APE_Product_MDS+';'+$Label.APE_Product_MDS_Teluw,  WelcomeCall_Product_Code_Plan__c+';' ), ((	Total_Premium__c* IF(WelcomeCall_Payment_Type__c == 'A',1, IF(WelcomeCall_Payment_Type__c == 'S',2, IF(WelcomeCall_Payment_Type__c == 'Q',4, 12)))
)+( WelcomeCall_Lump_Sum__c *0.1)), 

IF(CONTAINS( $Label.APE_Product_Single_Premium ,WelcomeCall_Product_Code_Plan__c+';'), 	
(Total_Premium__c+WelcomeCall_Lump_Sum__c )*0.1, 

IF(CONTAINS( $Label.APE_Product_Health ,WelcomeCall_Product_Code_Plan__c+';'), (	Total_Premium__c + WelcomeCall_Lump_Sum__c ) * IF(WelcomeCall_Payment_Type__c == 'A',1, IF(WelcomeCall_Payment_Type__c == 'S',2, IF(WelcomeCall_Payment_Type__c == 'Q',4, 12))),0
)
))
